// Package testutil contains helpers shared by tests across internal packages.
package testutil

import (
	"encoding/hex"
	"os"
	"path/filepath"
	"testing"
)

const successGuardWasmHex = ""

// WriteSuccessGuardWasm writes a guard WASM fixture whose label_agent export
// returns a non-empty approved integrity label.
func WriteSuccessGuardWasm(t testing.TB) string {
	t.Helper()

	wasm, err := hex.DecodeString(successGuardWasmHex)
	if err != nil {
		t.Fatalf("decode success guard WASM fixture: %v", err)
	}

	path := filepath.Join(t.TempDir(), "guard.wasm")
	if err := os.WriteFile(path, wasm, 0o600); err != nil {
		t.Fatalf("write success guard WASM fixture: %v", err)
	}
	return path
}
